effect.shader:
// Bevel + Light Sweep (official-style AM shader)
// - Only AM builtins; no dynamic loops/derivatives

const float PI = 3.141592653589793;

void main(){
  vec2 uv = acScreenNorm;
  vec4 src = texture2DCv(inputImg.texture, uv);

  // Texture texel size
  vec2 texel = 1.0 / getTexSize(inputImg.size);

  // Alpha gradient (Sobel-lite, 4 taps)
  float a_t = texture2DCv(inputImg.texture, uv + vec2(0.0,  texel.y)).a;
  float a_b = texture2DCv(inputImg.texture, uv + vec2(0.0, -texel.y)).a;
  float a_r = texture2DCv(inputImg.texture, uv + vec2( texel.x, 0.0)).a;
  float a_l = texture2DCv(inputImg.texture, uv + vec2(-texel.x, 0.0)).a;
  vec2 grad = vec2(a_r - a_l, a_t - a_b);
  float edgeStrength = length(grad);

  // Bevel lighting with a fixed light from top-left (135deg)
  float bevelAngle = radians(135.0);
  vec2 lightDir = normalize(vec2(cos(bevelAngle), sin(bevelAngle)));
  float lighting = dot(normalize(grad + 1e-6), lightDir);

  // Edge thickness: map px -> threshold in gradient domain
  float thickness = edgeThickness * 0.01; // empirical mapping
  float bevelMask = smoothstep(0.0, thickness + 1e-6, edgeStrength);

  float softness = 0.5;
  float powExp = 1.0 + (1.0 - softness) * 4.0;
  float highlight = pow(max(0.0,  lighting), powExp);
  float shadow    = pow(max(0.0, -lighting), powExp);

  float edgeGain = edgeIntensity / 100.0;
  vec3 beveled = src.rgb;
  beveled = mix(beveled, vec3(1.0), highlight * bevelMask * edgeGain);
  beveled = mix(beveled, vec3(0.0), shadow    * bevelMask * edgeGain);

  // Sweep line setup (static; no auto animation)
  vec2 centerPx = center; // in pixels
  vec2 centerUV = centerPx / acScreenSize; // normalize
  vec2 p = uv - centerUV;
  // aspect compensation
  p.x *= acScreenSize.x / max(acScreenSize.y, 1.0);
  float ang = radians(directionDeg);
  vec2 dir = vec2(cos(ang), sin(ang));
  vec2 nrm = vec2(-dir.y, dir.x);

  float width = widthPx / max(acScreenSize.y, 1.0); // px -> uv units (y-based)
  float d = abs(dot(p, nrm));

  // Beam + soft glow
  float beam = pow(1.0 - smoothstep(0.0, width, d), 8.0);
  float glow = (1.0 - smoothstep(0.0, width * 5.0, d)) * 0.4;
  float sweep = (beam + glow) * (sweepIntensity / 25.0);

  // Edge boost when sweep hits edges
  sweep += bevelMask * beam * 2.0;

  // Light color and reception blend
  vec3 sweepCol = lightColor.rgb * sweep;
  vec3 outRGB;
  if(int(lightReception)==0){
    // Add
    outRGB = beveled + sweepCol;
  } else {
    // Screen
    outRGB = 1.0 - (1.0 - beveled) * (1.0 - sweepCol);
  }

  // Rim Light (inner edge band): sample alpha inward along edge normal
  vec2 n = normalize(grad + 1e-6);
  float rimWidth = rimWidthPx / max(acScreenSize.y, 1.0);
  float rang = radians(rimAngleDeg);
  vec2 rn = vec2(cos(rang) * n.x - sin(rang) * n.y, sin(rang) * n.x + cos(rang) * n.y);
  float a_in_rim = texture2DCv(inputImg.texture, uv - rn * rimWidth).a;
  float rimBand = clamp(src.a - a_in_rim, 0.0, 1.0);
  // shape the band softly
  rimBand = smoothstep(0.0, 0.6, rimBand);
  vec3 rimCol = rimColor.rgb * rimBand * (rimIntensity / 100.0);
  if(int(rimReception)==0){
    outRGB += rimCol;
  } else {
    outRGB = 1.0 - (1.0 - outRGB) * (1.0 - rimCol);
  }

  // Inner Light (broader inner glow from edge inward)
  float innerWidth = innerWidthPx / max(acScreenSize.y, 1.0);
  float a_in_inner = texture2DCv(inputImg.texture, uv - n * innerWidth).a;
  float innerBand = clamp(src.a - a_in_inner, 0.0, 1.0);
  // boost and soften
  innerBand = 1.0 - exp(-innerBand * 3.0);
  vec3 innerCol = innerColor.rgb * innerBand * (innerIntensity / 100.0);
  if(int(innerReception)==0){
    outRGB += innerCol;
  } else {
    outRGB = 1.0 - (1.0 - outRGB) * (1.0 - innerCol);
  }

  float aOut = src.a * alpha;
  gl_FragColor = vec4(outRGB, 1.0) * aOut;
}
